"""
Template-based report rendering.

The LLM returns a compact JSON "report spec" (headline, narrative text, and the
numbers to show). Python does the financial math and renders the HTML/SVG from
fixed templates. This keeps the LLM output small, which is what makes the
report fast: generation time scales with output tokens.
"""

import html
import math
from datetime import date

HS_SALARY = 46_748
LOAN_RATE = 0.0653
REPAYMENT_YEARS = 20

DISCLAIMER = (
    "Generated by AI using data from BLS (May 2024), College Scorecard, and O*NET. "
    "For informational purposes only, not financial or career advice. "
    "AI analysis may contain errors; verify figures before making decisions. Generated {today}."
)

REPORT_SPEC_SYSTEM_PROMPT = """You write the content for a personalized college and career report. You receive raw data from tool calls and the user's intake profile. The page layout, CSS, charts, and financial math are handled by code. You only return JSON content. Keep it compact: no HTML, no markdown.

RESPOND WITH ONLY VALID JSON matching this shape:
{
  "summary": "1-2 sentence plain text takeaway for chat",
  "headline": "bold 1-2 sentence personalized takeaway",
  "baseline_salary": 46748,
  "baseline_label": "High school diploma",
  "options": [
    {"name": "Electrician", "short_label": "Electrician", "education": "4-5 yr apprenticeship", "years_in_school": 0, "annual_cost": 0, "expected_salary": 61590, "note": "Bright outlook"}
  ],
  "sections": [
    {
      "title": "Section heading",
      "what_it_means": "One 'What this means for you' sentence.",
      "bullets": ["optional short point"],
      "table": {"columns": ["School", "Net price"], "rows": [["UF", "$9,400"]]},
      "chart": {"title": "Median salary", "x_label": "Annual Salary ($)", "y_label": "Occupation", "unit": "usd", "bars": [{"label": "Electrician", "value": 61590}]}
    }
  ],
  "limitations": ["short honest caveat"]
}

FIELD RULES:
- options: one entry per path being compared (career, school, or program). Code computes education cost (annual_cost x years_in_school), opportunity cost, total investment, monthly loan payment (6.53% over 20 years), and payoff timeline, and renders the financial table and payoff chart. Do not compute these yourself.
  * years_in_school: years of full-time school still required (0 for no school). annual_cost: annual net price or tuition in dollars (0 if none).
  * expected_salary: annual salary in dollars from the tool data.
  * Include the baseline as an option only when the path format asks for it as a row (it will show zero cost).
- baseline_salary: 46748 (HS diploma) unless the user gave a current salary; then use it. baseline_label names it.
- sections: 2-4 sections ordered by importance to this user. table, chart, and bullets are each optional; include only what adds value. Do not repeat the financial breakdown. Short chart labels (e.g. "CO Mines"). chart unit is one of: usd, percent, years, number.
- Table cells are short display strings, already formatted.
- Never use the words "major" or "break-even". Say "degree" or "program", and "payoff timeline".
- BLS caps reported salaries at $239,200/yr; note this where relevant.
- For income-based net price data, highlight the bracket closest to the user's situation if known.

PATH-SPECIFIC CONTENT (intake "path_type"):
path1 (college vs vocational vs work): options are exactly five rows: HS diploma baseline (zero cost, baseline salary), Cashier, Electrician, Bachelor's degree median, user's chosen occupation.
path2 (comparing schools): options are the top 5 schools ranked by the user's chosen metric. A section table shows ONLY the metrics the user toggled in compare_metrics.
path3 (comparing programs at school): options are the programs. A section compares school-specific earnings (College Scorecard) with national occupation salary (BLS), labeling sources, plus bright outlook status from O*NET.
path4 (compare career tracks): options are the careers. Use current_position, education_level, current_field, and current_role for context (credit for existing education, gap from current role).
path5 (path to career): options are the realistic routes to the target. One section is a roadmap: bullets as ordered steps with timeline, plus gap analysis between current and required education.
"""


def _esc(value) -> str:
    return html.escape(str(value), quote=True)


def _num(value, default: float = 0.0) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def _usd(value: float) -> str:
    return f"${value:,.0f}"


def _fmt(value: float, unit: str) -> str:
    if unit == "usd":
        return _usd(value)
    if unit == "percent":
        return f"{value:.0f}%"
    if unit == "years":
        return f"{value:.1f} yrs"
    return f"{value:,.0f}"


def monthly_payment(principal: float, rate: float = LOAN_RATE, years: int = REPAYMENT_YEARS) -> float:
    if principal <= 0:
        return 0.0
    r = rate / 12
    n = years * 12
    return principal * r / (1 - (1 + r) ** -n)


def compute_financials(option: dict, baseline_salary: float) -> dict:
    years = _num(option.get("years_in_school"))
    education_cost = _num(option.get("annual_cost")) * years
    opportunity_cost = baseline_salary * years
    total = education_cost + opportunity_cost
    salary = _num(option.get("expected_salary"))
    delta = salary - baseline_salary
    if total == 0:
        payoff = 0.0
    elif delta > 0:
        payoff = total / delta
    else:
        payoff = None
    return {
        "education_cost": education_cost,
        "opportunity_cost": opportunity_cost,
        "total_investment": total,
        "monthly_payment": monthly_payment(education_cost),
        "salary": salary,
        "payoff_years": payoff,
    }


def _nice_max(value: float) -> float:
    """Round the axis max up to 1, 2, 2.5, or 5 x 10^n so ticks are round numbers."""
    if value <= 0:
        return 1.0
    step = value / 4
    mag = 10 ** math.floor(math.log10(step))
    for m in (1, 2, 2.5, 5, 10):
        if step <= m * mag:
            return m * mag * 4
    return value


def _short(label: str, limit: int = 20) -> str:
    return label if len(label) <= limit else label[: limit - 1].rstrip() + "…"


def bar_chart(title: str, x_label: str, y_label: str, bars: list[dict], unit: str = "number") -> str:
    """Horizontal bar chart: labels left of bars, values right, sorted desc, gridlines."""
    bars = sorted(
        ({"label": str(b.get("label", "")), "value": _num(b.get("value"))} for b in bars),
        key=lambda b: b["value"],
        reverse=True,
    )
    if not bars:
        return ""
    left, right, top, bar_h, gap = 150, 90, 20, 28, 12
    width = 700
    plot_w = width - left - right
    plot_h = len(bars) * (bar_h + gap) - gap
    height = top + plot_h + 50
    max_v = _nice_max(max(b["value"] for b in bars))
    ticks = 4
    parts = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{_esc(title)}">']
    for i in range(ticks + 1):
        x = left + plot_w * i / ticks
        v = max_v * i / ticks
        parts.append(f'<line x1="{x:.1f}" y1="{top}" x2="{x:.1f}" y2="{top + plot_h}" class="grid"/>')
        parts.append(f'<text x="{x:.1f}" y="{top + plot_h + 16}" class="tick" text-anchor="middle">{_esc(_fmt(v, unit))}</text>')
    for i, b in enumerate(bars):
        y = top + i * (bar_h + gap)
        w = plot_w * max(b["value"], 0) / max_v
        cy = y + bar_h / 2 + 5
        parts.append(f'<text x="{left - 8}" y="{cy:.1f}" class="lbl" text-anchor="end"><title>{_esc(b["label"])}</title>{_esc(_short(b["label"]))}</text>')
        parts.append(f'<rect x="{left}" y="{y}" width="{w:.1f}" height="{bar_h}" class="bar" rx="3"/>')
        parts.append(f'<text x="{left + w + 6:.1f}" y="{cy:.1f}" class="val">{_esc(_fmt(b["value"], unit))}</text>')
    parts.append(f'<text x="{left + plot_w / 2:.1f}" y="{height - 6}" class="axis" text-anchor="middle">{_esc(x_label)}</text>')
    parts.append(
        f'<text x="14" y="{top + plot_h / 2:.1f}" class="axis" text-anchor="middle" '
        f'transform="rotate(-90 14 {top + plot_h / 2:.1f})">{_esc(y_label)}</text>'
    )
    parts.append("</svg>")
    return f'<figure><figcaption>{_esc(title)}</figcaption>{"".join(parts)}</figure>'


def _table(columns: list, rows: list) -> str:
    head = "".join(f"<th>{_esc(c)}</th>" for c in columns)
    body = "".join("<tr>" + "".join(f"<td>{_esc(c)}</td>" for c in row) + "</tr>" for row in rows)
    return f'<div class="tbl"><table><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div>'


def _financial_section(options: list[dict], baseline_salary: float, baseline_label: str) -> str:
    if not options:
        return ""
    rows = []
    payoff_bars = []
    for opt in options:
        f = compute_financials(opt, baseline_salary)
        payoff = f["payoff_years"]
        payoff_text = "Does not pay off at this salary" if payoff is None else ("Immediate" if payoff == 0 else f"{payoff:.1f} yrs")
        rows.append([
            opt.get("name", ""),
            opt.get("education", ""),
            _usd(f["education_cost"]),
            _usd(f["opportunity_cost"]),
            _usd(f["total_investment"]),
            _usd(f["monthly_payment"]),
            _usd(f["salary"]),
            payoff_text,
        ])
        if payoff:
            payoff_bars.append({"label": opt.get("short_label") or opt.get("name", ""), "value": payoff})
    table = _table(
        ["Option", "Education", "Education cost", "Opportunity cost", "Total investment",
         "Monthly loan payment", "Expected salary", "Payoff timeline"],
        rows,
    )
    chart = bar_chart("Payoff timeline (options with an education cost)", "Years after graduation to recoup investment", "Option", payoff_bars, "years")
    return (
        '<section><h2>Financial breakdown</h2>'
        f'<p class="note">Baseline: {_esc(baseline_label)} at {_usd(baseline_salary)}/yr. '
        f'Loans at {LOAN_RATE * 100:.2f}% over {REPAYMENT_YEARS} years. '
        'Opportunity cost is baseline earnings given up while in school.</p>'
        f"{table}{chart}</section>"
    )


def _section(sec: dict) -> str:
    out = [f'<section><h2>{_esc(sec.get("title", ""))}</h2>']
    bullets = sec.get("bullets") or []
    if bullets:
        out.append("<ul>" + "".join(f"<li>{_esc(b)}</li>" for b in bullets) + "</ul>")
    table = sec.get("table")
    if isinstance(table, dict) and table.get("rows"):
        out.append(_table(table.get("columns", []), table["rows"]))
    chart = sec.get("chart")
    if isinstance(chart, dict) and chart.get("bars"):
        out.append(bar_chart(
            chart.get("title", ""), chart.get("x_label", ""), chart.get("y_label", ""),
            chart["bars"], chart.get("unit", "number"),
        ))
    if sec.get("what_it_means"):
        out.append(f'<p class="means"><strong>What this means for you:</strong> {_esc(sec["what_it_means"])}</p>')
    out.append("</section>")
    return "".join(out)


