SAVE_BUTTON = (
    '<button class="save-btn" onclick="(function(){var a=document.createElement(\'a\');'
    "a.href='data:text/html,'+encodeURIComponent(document.documentElement.outerHTML);"
    "a.download='next-right-step-report.html';a.click()})()\">Save Report</button>"
)


def render_report(spec: dict) -> str:
    baseline_salary = _num(spec.get("baseline_salary"), HS_SALARY) or HS_SALARY
    baseline_label = spec.get("baseline_label") or "High school diploma"
    options = [o for o in spec.get("options") or [] if isinstance(o, dict)]
    sections = [s for s in spec.get("sections") or [] if isinstance(s, dict)]
    limitations = spec.get("limitations") or []

    body = [
        "<h1>Your Next Right Step report</h1>",
        f'<p class="headline">{_esc(spec.get("headline", ""))}</p>',
    ]
    body.extend(_section(s) for s in sections)
    body.append(_financial_section(options, baseline_salary, baseline_label))
    if limitations:
        body.append(
            "<section><h2>Limitations</h2><ul>"
            + "".join(f"<li>{_esc(item)}</li>" for item in limitations)
            + "</ul></section>"
        )
    body.append(f"<footer>{_esc(DISCLAIMER.format(today=date.today().strftime('%B %d, %Y')))}</footer>")

    return (
        "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\">"
        '<meta name="viewport" content="width=device-width,initial-scale=1">'
        "<title>Next Right Step Report</title>"
        '<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap" rel="stylesheet">'
        f"<style>{CSS}</style></head><body>{SAVE_BUTTON}<main>{''.join(body)}</main></body></html>"
    )
